package com.lqq.supportflow.knowledge.infrastructure.storage;
import com.lqq.supportflow.knowledge.domain.*; import io.minio.*; import java.io.InputStream; import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.stereotype.Component;
@Component @ConditionalOnProperty(prefix="supportflow.storage.minio",name="enabled",havingValue="true") public class MinioKnowledgeObjectStorage implements KnowledgeObjectStorage { private final MinioClient client; private final String bucket; public MinioKnowledgeObjectStorage(@Value("${supportflow.storage.minio.endpoint}") String endpoint,@Value("${supportflow.storage.minio.access-key}") String accessKey,@Value("${supportflow.storage.minio.secret-key}") String secretKey,@Value("${supportflow.storage.minio.bucket:supportflow-knowledge}") String bucket){this.client=MinioClient.builder().endpoint(endpoint).credentials(accessKey,secretKey).build();this.bucket=bucket;} public StoredKnowledgeObject put(Long tenantId,Long knowledgeBaseId,String contentHash,String fileName,String contentType,InputStream content,long size){try{if(!client.bucketExists(BucketExistsArgs.builder().bucket(bucket).build()))client.makeBucket(MakeBucketArgs.builder().bucket(bucket).build());String key="tenants/"+tenantId+"/knowledge-bases/"+knowledgeBaseId+"/"+contentHash;client.putObject(PutObjectArgs.builder().bucket(bucket).object(key).stream(content,size,-1).contentType(contentType).build());return new StoredKnowledgeObject(key,size,contentType);}catch(Exception exception){throw new IllegalArgumentException("cannot store document",exception);}} public InputStream open(String objectKey){try{return client.getObject(GetObjectArgs.builder().bucket(bucket).object(objectKey).build());}catch(Exception exception){throw new IllegalArgumentException("cannot read document",exception);}}}
